#!/usr/bin/env python3
"""patch_271_fill_part2.py — Fill all remaining under-50 arrays to 50+ items."""
import json, os

DATA = os.path.join(os.path.dirname(__file__), '..', 'data')

def load(fn):
    with open(os.path.join(DATA, fn), encoding='utf-8') as f:
        return json.load(f)

def save(fn, d):
    with open(os.path.join(DATA, fn), 'w', encoding='utf-8') as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    print(f'{fn}: saved')

def ext_hl(d, k, new):
    """Extend HL array inside dict-with-items or direct list, dedup by name"""
    v = d.get(k)
    if v is None: return
    if isinstance(v, dict) and 'items' in v:
        lst = v['items']
    elif isinstance(v, list):
        lst = v
    else:
        return
    existing = {x['name'] for x in lst}
    added = [x for x in new if x['name'] not in existing]
    lst.extend(added)
    print(f'  {k}: {len(lst)} items (+{len(added)})')

def ext_m(d, k, new):
    """Extend match array (keyed by n), dedup by n"""
    v = d.get(k)
    if v is None: return
    if isinstance(v, dict) and 'items' in v:
        lst = v['items']
    elif isinstance(v, list):
        lst = v
    else:
        return
    existing = {x['n'] for x in lst}
    added = [x for x in new if x['n'] not in existing]
    lst.extend(added)
    print(f'  {k}: {len(lst)} items (+{len(added)})')

def ext_p(d, k, new):
    """Extend pin array, dedup by n"""
    v = d.get(k)
    if v is None: return
    if isinstance(v, dict) and 'items' in v:
        lst = v['items']
    elif isinstance(v, list):
        lst = v
    else:
        return
    existing = {x['n'] for x in lst}
    added = [x for x in new if x['n'] not in existing]
    lst.extend(added)
    print(f'  {k}: {len(lst)} items (+{len(added)})')

def ext_kultur(d, k, new):
    """Extend kultur array — varied formats, dedup by n or name"""
    if not isinstance(d.get(k), list):
        print(f'  SKIP {k}: not a list')
        return
    lst = d[k]
    existing_set = set()
    for x in lst:
        if isinstance(x, dict):
            key = x.get('n') or x.get('name') or str(x)
        else:
            key = str(x)
        existing_set.add(key)
    added = []
    for x in new:
        if isinstance(x, dict):
            key = x.get('n') or x.get('name') or str(x)
        else:
            key = str(x)
        if key not in existing_set:
            lst.append(x)
            existing_set.add(key)
            added.append(x)
    print(f'  {k}: {len(lst)} items (+{len(added)})')

