print('\n=== tiere_match.json ===')
d = load('tiere_match.json')

def ext_tiere_match(d, k, new):
    v = d.get(k)
    if v is None: return
    if isinstance(v, list): lst = v
    elif isinstance(v, dict) and 'items' in v: lst = v['items']
    else: return
    existing = {x['n'] for x in lst}
    added = [x for x in new if x['n'] not in existing]
    lst.extend(added)
    print(f'  {k}: {len(lst)} items (+{len(added)})')

