fn = 'timeline.json'
d = load(fn)

v = d.get('sport_stadien')
if isinstance(v, dict) and 'items' in v: lst = v['items']
elif isinstance(v, list): lst = v
else: lst = []
existing = {x['n'] for x in lst}
new_items = [
    {"n": "Estadio Azteca (1966)", "year": 1966, "hint": "Mexiko-Stadt — WM 1970 und 1986"},
]
added = [x for x in new_items if x['n'] not in existing]
lst.extend(added)
print(f'  sport_stadien: {len(lst)} items (+{len(added)})')

save('timeline.json', d)

